  switch Type.info(expected()) {
  | String =>
    %code(
      switch %res.hole(json) {
      | String(text) => text
      | _ => fail("expected a string")
      }
    )
  | Int =>
    %code(
      switch %res.hole(json) {
      | Number(number) => Float.toInt(number)
      | _ => fail("expected a number")
